import json

# Get data from previous nodes
user_response = node_outputs.get('fetch_user', {})
posts_response = node_outputs.get('fetch_posts', {})

# Parse JSON responses
user_data = json.loads(user_response.get('body', '{}')) if isinstance(user_response.get('body'), str) else user_response.get('body', {})
posts_data = json.loads(posts_response.get('body', '[]')) if isinstance(posts_response.get('body'), str) else posts_response.get('body', [])

# Aggregate data
output = {
  'user_profile': {
    'id': user_data.get('id'),
    'name': user_data.get('name'),
    'email': user_data.get('email'),
    'company': user_data.get('company', {}).get('name', 'N/A')
  },
  'statistics': {
    'total_posts': len(posts_data),
    'avg_title_length': sum(len(post.get('title', '')) for post in posts_data) / len(posts_data) if posts_data else 0
  },
  'recent_posts': [
    {
      'id': post.get('id'),
      'title': post.get('title'),
      'excerpt': post.get('body', '')[:100] + '...'
    }
    for post in posts_data[:3]
  ]
}

import json
import datetime

aggregated = node_outputs.get('aggregate_data', {})

# Create formatted report
report = {
  'generated_at': datetime.datetime.now().isoformat(),
  'user_summary': {
    'name': aggregated.get('user_profile', {}).get('name'),
    'email': aggregated.get('user_profile', {}).get('email'),
    'company': aggregated.get('user_profile', {}).get('company')
  },
  'content_stats': aggregated.get('statistics', {}),
  'latest_posts': aggregated.get('recent_posts', []),
  'status': 'success'
}

output = {
  'report': report,
  'json_output': json.dumps(report, indent=2)
}
